// src/pages/MarketPrices.jsx
import { useState } from "react";
import C from "../constants/colors";
import { MARKET_DATA } from "../constants/data";
import Card from "../components/ui/Card";
import Badge from "../components/ui/Badge";
import TrendPill from "../components/ui/TrendPill";

function MarketPrices({ t }) {
  const [cat,    setCat]    = useState("All");
  const [search, setSearch] = useState("");

  // ── Translation strings ───────────────────────────────────────────────────
  const TX = {
    title:      t("market.title")     || "Market Prices",
    subtitle:   t("market.subtitle")  || "Live mandi prices across Tamil Nadu",
    search:     t("market.search")    || "Search crop…",
    all:        t("market.all")       || "All",
    modal:      t("market.modal")     || "Modal",
    min:        t("market.min")       || "Min",
    max:        t("market.max")       || "Max",
    market:     t("market.market")    || "Market",
    trend:      t("market.trend")     || "Trend",
    priceUnit:  t("market.priceUnit") || "₹/quintal",
    up:         t("market.up")        || "↑ Rising",
    down:       t("market.down")      || "↓ Falling",
    flat:       t("market.flat")      || "→ Stable",
    category:   t("common.filter")    || "Category",
    aiTitle:    "💡 AI Market Intelligence",
    crop:       t("map.crop")         || "Crop",
    noData:     t("common.noData")    || "No crops found",
  };

  // ── AI sell/hold advice translated ────────────────────────────────────────
  const aiAdvice = {
    en: {
      sell: "<strong>Sell now:</strong> Jasmine (↑10.2%), Green Chilli (↑8.1%), Onion (↑8.1%) — festival season peak.",
      hold: "<strong>Hold:</strong> Turmeric (↑4.5%), Cardamom (↑3.2%) — uptrend continuing for 2 more weeks.",
      wait: "<strong>Wait:</strong> Toor Dal (↓2.3%), Cotton (↓2.3%) — seasonal correction, hold for 3 weeks.",
      rice: "<strong>Best time to sell rice:</strong> Pre-harvest demand — sell stored stocks within 7 days.",
    },
    ta: {
      sell: "<strong>இப்போது விற்கவும்:</strong> மல்லிகை (↑10.2%), பச்சை மிளகாய் (↑8.1%), வெங்காயம் (↑8.1%) — பண்டிகை கால உச்சம்.",
      hold: "<strong>தொடர்ந்து வைக்கவும்:</strong> மஞ்சள் (↑4.5%), ஏலக்காய் (↑3.2%) — இன்னும் 2 வாரம் விலை உயரும்.",
      wait: "<strong>காத்திருக்கவும்:</strong> தூவரம் பருப்பு (↓2.3%), பருத்தி (↓2.3%) — 3 வாரம் காக்கவும்.",
      rice: "<strong>நெல் விற்க சிறந்த நேரம்:</strong> அறுவடைக்கு முன் தேவை அதிகம் — 7 நாளில் விற்கவும்.",
    },
    hi: {
      sell: "<strong>अभी बेचें:</strong> चमेली (↑10.2%), हरी मिर्च (↑8.1%), प्याज (↑8.1%) — त्योहारी सीजन पीक।",
      hold: "<strong>रोकें:</strong> हल्दी (↑4.5%), इलायची (↑3.2%) — 2 हफ्ते और तेजी जारी रहेगी।",
      wait: "<strong>इंतजार करें:</strong> तूर दाल (↓2.3%), कपास (↓2.3%) — सीजनल करेक्शन, 3 हफ्ते रुकें।",
      rice: "<strong>चावल बेचने का सबसे अच्छा समय:</strong> फसल से पहले मांग — 7 दिनों में स्टॉक बेचें।",
    },
  };

  // detect current lang from t function by checking a known key
  const currentLang = t("market.up") === "↑ உயர்கிறது" ? "ta" : t("market.up") === "↑ बढ़ रहा है" ? "hi" : "en";
  const advice = aiAdvice[currentLang] || aiAdvice.en;

  const cats = [TX.all, "Vegetable","Cereal","Pulse","Oilseed","Cash Crop","Fruit","Flower","Spice","Plantation"];

  const filtered = MARKET_DATA.filter(p =>
    (cat === TX.all || p.category === cat) &&
    (!search || p.crop.toLowerCase().includes(search.toLowerCase()))
  );

  return (
    <div style={{ padding: 22 }}>
      <h1 style={{ fontSize: 21, fontWeight: 600, color: C.text, margin: "0 0 4px" }}>
        📈 {TX.title}
      </h1>
      <p style={{ color: C.muted, fontSize: 13, margin: "0 0 14px" }}>
        {TX.subtitle} • 42 {t("map.crop") ? t("map.crop").toLowerCase() + "s" : "crops"} • Updated today 08:30 AM
      </p>

      {/* Search + category filters */}
      <div style={{ display: "flex", gap: 8, marginBottom: 12, flexWrap: "wrap", alignItems: "center" }}>
        <input
          value={search}
          onChange={e => setSearch(e.target.value)}
          placeholder={TX.search}
          style={{ padding: "8px 12px", borderRadius: 8, border: `1px solid ${C.border}`, fontSize: 13, outline: "none", width: 200, color: C.text }}
        />
        {cats.map(c => (
          <button key={c} onClick={() => setCat(c)} style={{
            padding:    "6px 13px",
            borderRadius: 16,
            fontSize:   12.5,
            cursor:     "pointer",
            border:     `1.5px solid ${cat === c ? C.bg2 : C.border}`,
            background: cat === c ? C.pale : C.white,
            color:      cat === c ? C.bg2 : C.muted,
            fontWeight: cat === c ? 600 : 400,
          }}>
            {c}
          </button>
        ))}
      </div>

      {/* Price table */}
      <Card style={{ padding: 0, overflow: "hidden", marginBottom: 14 }}>

        {/* Table header */}
        <div style={{
          display:     "grid",
          gridTemplateColumns: "1.8fr 1fr 1fr 1fr 0.8fr 1fr",
          padding:     "9px 14px",
          background:  C.pale,
          fontSize:    11.5,
          fontWeight:  600,
          color:       C.text,
          borderBottom: `1px solid ${C.border}`,
        }}>
          <span>{TX.crop}</span>
          <span>{TX.priceUnit} ({TX.modal})</span>
          <span>{TX.min}</span>
          <span>{TX.max}</span>
          <span>{TX.category}</span>
          <span>{TX.trend}</span>
        </div>

        {/* Rows */}
        <div style={{ maxHeight: 480, overflowY: "auto" }}>
          {filtered.length === 0 && (
            <div style={{ padding: "24px", textAlign: "center", color: C.muted, fontSize: 13 }}>
              {TX.noData}
            </div>
          )}
          {filtered.map((p, i) => (
            <div key={p.crop} style={{
              display:     "grid",
              gridTemplateColumns: "1.8fr 1fr 1fr 1fr 0.8fr 1fr",
              padding:     "11px 14px",
              borderBottom: `1px solid ${C.border}`,
              background:  i % 2 ? C.bg : C.white,
              alignItems:  "center",
            }}>
              <div>
                <span style={{ fontSize: 14, fontWeight: 500, color: C.text }}>{p.crop}</span>
                <span style={{ fontSize: 11, color: C.muted, marginLeft: 6 }}>{p.market}</span>
              </div>
              <span style={{ fontSize: 14, fontWeight: 700, color: C.text }}>₹{p.modal.toLocaleString()}</span>
              <span style={{ fontSize: 12.5, color: C.muted }}>₹{p.min.toLocaleString()}</span>
              <span style={{ fontSize: 12.5, color: C.muted }}>₹{p.max.toLocaleString()}</span>
              <Badge color={C.muted} bg={C.bg}>{p.category.split(" ")[0]}</Badge>
              <TrendPill trend={p.trend} change={p.change} />
            </div>
          ))}
        </div>
      </Card>

      {/* AI Market Intelligence — translated */}
